    +'<p>'+esc(n[2])+'</p><p class="ice-pf"><span class="ice-rk"><i aria-hidden="true"></i>'+esc(rname(n[0]))+'</span>'
    +(n[1]?'<span class="ice-hearts">'+ICON_HEART+n[1]+'<span class="wk-vh"> hearts</span></span>':'')+'</p></article>';
