    +'<div class="ice-posts">'+show.map(postit).join('')+'</div>';
  if(more.length&&window.HOTP&&HOTP.tab) h+='<div class="ice-more">'+HOTP.tab({label:'More notes ('+more.length+')',id:'wk-ice-more-'+id.replace('.','-'),html:'<div class="ice-posts">'+more.map(function(n,k){return postit(n,k+3);}).join('')+'</div>'})+'</div>';
  h+='<nav class="ice-nav" aria-label="Themes">'
    +(pv?'<button type="button" class="wk-pill ghost" data-ice="'+pv.id+'">'+ICON_UP+'<span>'+esc(pv.short)+'</span></button>':'<span></span>')
    +(nx?'<button type="button" class="wk-pill" data-ice="'+nx.id+'"><span>Next: '+esc(nx.short)+'</span>'+ICON_DOWN+'</button>':'')
