    HUBS.forEach(function(H){
      var nx=H.x+(H.tx-H.x)*kp, ny=H.y+(H.ty-H.y)*kp;
      if(Math.abs(H.tx-nx)>.05||Math.abs(H.ty-ny)>.05)moving=true;else{nx=H.tx;ny=H.ty;}
      H.x=nx;H.y=ny;
      var tr=H.R*(H.el.classList.contains('on')?1.04:1), c=H.cr+(tr-H.cr)*kr; if(Math.abs(tr-c)>.04)moving=true;else c=tr; H.cr=c;
      H.X=H.x+amp*H.ax*Math.sin(T*H.fx+H.ph); H.Y=H.y+amp*H.ay*Math.cos(T*H.fy+H.ph*1.3);
      H.el.style.transform='translate3d('+f1(H.X-c)+'px,'+f1(H.Y-c)+'px,0)';
      if(Math.abs(H.sz-c)>.04){H.sz=c;H.el.style.width=H.el.style.height=(2*c).toFixed(2)+'px';}
    });
    SATS.forEach(function(S){
      var nx=S.x+(S.tx-S.x)*kp, ny=S.y+(S.ty-S.y)*kp;
      if(Math.abs(S.tx-nx)>.05||Math.abs(S.ty-ny)>.05)moving=true;else{nx=S.tx;ny=S.ty;}
      S.x=nx;S.y=ny;
      var gv=S.gv+(S.g0-S.gv)*kg; if(Math.abs(S.g0-gv)>.002)moving=true;else gv=S.g0; S.gv=gv;
      var eg=eout(gv), H=S.h;
      var bx=S.x+amp*S.ax*Math.sin(T*S.fx+S.ph), by=S.y+amp*S.ay*Math.cos(T*S.fy+S.ph*1.3);
      S.X=H.X+(bx-H.X)*eg; S.Y=H.Y+(by-H.Y)*eg;
      var tr=S.rs*S.k*(S.isNew?(.15+.85*eg):1), c=S.cr+(tr-S.cr)*kr; if(Math.abs(tr-c)>.04)moving=true;else c=tr; S.cr=c;
      var hidden=S.isNew&&gv<=.001;
      if(hidden!==S.hid){S.hid=hidden;S.el.style.visibility=hidden?'hidden':'';S.path.style.visibility=hidden?'hidden':'';
        if(view.free){if(hidden)S.el.setAttribute('tabindex','-1');else S.el.removeAttribute('tabindex');}}
      S.el.style.opacity=S.isNew?Math.min(1,gv*2.5).toFixed(3):'';
      S.el.style.transform='translate3d('+f1(S.X-c)+'px,'+f1(S.Y-c)+'px,0)';
      if(Math.abs(S.sz-c)>.04){S.sz=c;S.el.style.width=S.el.style.height=(2*c).toFixed(2)+'px';}
      if(!hidden) S.path.setAttribute('d',tpath(H,S,S.X,S.Y,c));
      S.path.style.opacity=S.isNew?Math.min(1,gv*1.6).toFixed(3):'';
    });
