      e=BEL[w.id]={d:w.d,g:svgEl('path',{d:w.d,'class':'dv-bg'+w.x,style:sty}),c:svgEl('path',{d:w.d,'class':'dv-bc'+w.x+(w.rev?' rev':''),pathLength:'100',style:sty})};
