/* the top bar's glass: the droplet glides to the button under the pointer or keyboard focus; light follows the pointer */
function tbGlass(ctl) {
  const drop = $(".tb-drop", ctl);
  const to = (b) => { if (!b) { ctl.classList.remove("drop"); return; } ctl.style.setProperty("--dx", b.offsetLeft + "px"); ctl.style.setProperty("--dw", b.offsetWidth + "px"); ctl.classList.add("drop"); };
  ctl.addEventListener("pointerover", (e) => to(e.target.closest(".tb-b"))); /* round 8: no per-move work; the droplet moves when the pointer reaches a new button */
  ctl.addEventListener("pointerleave", () => { if (!ctl.contains(document.activeElement) || !document.activeElement.matches(":focus-visible")) to(null); ctl.classList.remove("press"); });
  ctl.addEventListener("focusin", (e) => { if (e.target.matches(":focus-visible")) to(e.target.closest(".tb-b")); });
  ctl.addEventListener("focusout", () => setTimeout(() => { if (!ctl.contains(document.activeElement) && !ctl.matches(":hover")) to(null); }, 0));
  ctl.addEventListener("pointerdown", (e) => { const b = e.target.closest(".tb-b"); if (b) { to(b); ctl.classList.add("press"); } });
  addEventListener("pointerup", () => { ctl.classList.remove("press"); if (matchMedia("(hover:none)").matches) setTimeout(() => to(null), 450); });
  return drop;
}

